  const authoritativeMachineTotal = num(
    project.total_machine_cost,
    num(project.builder_calculation?.totals?.total_machine_cost, itemMachineTotal)
  );
  const machineAdjustment = authoritativeMachineTotal - itemMachineTotal;
  if (Math.abs(machineAdjustment) > 0.005) {
    parts.push(manualCostPart({
      key: "laser:machine-adjustment",
      name: "Laser Machine Cost Adjustment",
      type: "equipment",
      subtype: "machine_adjustment",
      sourcePath: "total_machine_cost",
      cost: machineAdjustment,
      calculation: { total_machine_cost: authoritativeMachineTotal, item_machine_cost: itemMachineTotal, adjustment: machineAdjustment },
    }));
  }

  const authoritativeLaborTotal = num(
    project.total_labor_cost,
    num(project.builder_calculation?.totals?.total_labor_cost, itemLaborTotal + fixedSetupCost)
  );
  const laborAdjustment = authoritativeLaborTotal - itemLaborTotal - fixedSetupCost;
  if (Math.abs(laborAdjustment) > 0.005) {
    parts.push(manualCostPart({
      key: "laser:labor-adjustment",
      name: "Laser Labor Adjustment",
      type: "labor",
      subtype: "labor_adjustment",
      sourcePath: "total_labor_cost",
      cost: laborAdjustment,
      calculation: { total_labor_cost: authoritativeLaborTotal, item_labor_cost: itemLaborTotal, fixed_setup_cost: fixedSetupCost, adjustment: laborAdjustment },
    }));
  }

  const authoritativeSupplies = num(
    project.total_supplies_cost,
    num(project.fixed_material_setup_cost, project.builder_calculation?.totals?.total_supplies_cost)
  );
  if (Math.abs(authoritativeSupplies) > 0.005) {
    parts.push(manualCostPart({
      key: "laser:fixed-material-setup",
      name: "Laser Material Setup / Consumables",
      type: "consumable",
      subtype: "material_setup",
      sourcePath: "total_supplies_cost",
      cost: authoritativeSupplies,
      calculation: { fixed_material_setup_cost: project.fixed_material_setup_cost, total_supplies_cost: authoritativeSupplies },
    }));
  }
  return parts;
}

function extractManualItems(project, moduleKey) {
  return (project.items || []).map((item, index) => makePart({
    key: `${moduleKey}:item:${index}`,
    name: item.description || `${moduleKey.toUpperCase()} item ${index + 1}`,
    type: "fabrication",
    subtype: item.item_type || moduleKey,
    sourcePath: `items[${index}]`,
    quantity: item.quantity || 1,
    unit: "item",
    unitCost: item.quantity ? num(item.item_total_cost) / num(item.quantity, 1) : 0,
    extendedCost: item.item_total_cost,
    builderData: item,
    calculation: item,
  }));
}

// Extraction memo (#413): keyed on the project object identity + module/
// options + catalogs identity. The same project re-rendered through sync
// paths skips re-extraction; any payload or catalog change recomputes.
const _extractCache = new WeakMap();

export function extractBuilderParts(moduleKey, project, catalogs = {}, options = {}) {
  if (!project) return [];
  if (typeof project !== "object") return _extractBuilderPartsComputed(moduleKey, project, catalogs, options);
  const key = `${moduleKey}|${options?.legacyMode ? 1 : 0}`;
  let byKey = _extractCache.get(project);
  const hit = byKey?.get(key);
  if (hit && hit.catalogs === catalogs) return hit.out;
  const out = _extractBuilderPartsComputed(moduleKey, project, catalogs, options);
  if (!byKey) { byKey = new Map(); _extractCache.set(project, byKey); }
  byKey.set(key, { catalogs, out });
  return out;
}

function _extractBuilderPartsComputed(moduleKey, project, catalogs = {}, options = {}) {
  switch (moduleKey) {
    case "foundation": return extractFoundation(project, catalogs);
    case "channel_letters": return extractChannel(project, catalogs);
    case "vinyl": return extractVinyl(project, catalogs, options);
    case "metal": return extractMetal(project);
    case "brick_stone": return extractBrick(project, catalogs, options);
    case "maintenance": return extractMaintenance(project, catalogs, options);
    case "painting": return extractPainting(project);
    case "cnc": return extractCNC(project);
    case "laser": return extractLaser(project);
    default: return extractManualItems(project, moduleKey || "legacy");
  }
}

function effectiveCurrentUnitCost(descriptor, row) {
  if (Number.isFinite(Number(descriptor.unit_cost)) && Number(descriptor.unit_cost) !== 0) {
    return Number(descriptor.unit_cost);
  }
  return genericUnitCost(row);
}

export async function syncBuilderParts({ builderProduct, sourceProject, acceptPrices = false, legacyMode = false, builderRecalculated = false, catalogsOverride = null, strictCatalogs = false, existingPartsOverride = null, inventoryRowsOverride = null, skipUnchangedWrites = false, planOnly = false, planTimestamp = "" }) {
  if (!builderProduct?.id || !sourceProject) {
    return {
      partCount: 0,
      detachedCount: 0,
      changedCount: 0,
      newPartCount: 0,
      removedPartCount: 0,
      writesPerformed: 0,
      recalcRequired: false,
      recalcReason: "",
      usesDirectLiveReprice: false,
      currentPartsTotal: 0,
      frozenPartsTotal: 0,
      currentMarkupTotal: 0,
      frozenMarkupTotal: 0,
      manualAddonFrozenTotal: 0,
      manualAddonCurrentTotal: 0,
      parts: [],
      partWritePlan: [],
    };
  }

  const catalogs = catalogsOverride || await loadBuilderCatalogs(builderProduct.module_key, { strict: strictCatalogs });
  const descriptors = extractBuilderParts(builderProduct.module_key, sourceProject, catalogs, { legacyMode });
  const existing = existingPartsOverride || await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProduct.id }, sort: "sort_order", label: "Builder Parts" });
  const byKey = new Map((existing || []).map((part) => [part.part_key, part]));
  const seen = new Set();
  const synced = [];
  let detachedCount = 0;
  let changedCount = 0;
  let newPartCount = 0;
  let removedPartCount = 0;
  let writesPerformed = 0;
  let recalcRequired = false;
  const recalcPartNames = [];
  const partWritePlan = [];
  const syncNow = () => planTimestamp || nowIso();
  const directLiveReprice = DIRECT_LIVE_REPRICE_MODULES.has(builderProduct.module_key);

  const writePartUpdate = async (old, patch) => {
    const step = {
      operation: "update",
      part_id: old.id,
      part_key: old.part_key,
      expected_updated_date: old.updated_date || "",
      patch,
    };
    partWritePlan.push(step);
    if (planOnly) return { ...old, ...patch };
    const saved = await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderPart,
      id: old.id,
      expectedUpdatedAt: old.updated_date || "",
      expectedFields: expectedBuilderEntityFields(old, patch),
      nextFields: patch,
      guardFields: { builder_product_id: old.builder_product_id },
      label: `Builder Part “${old.part_name || "Part"}” synchronization`,
    });
    writesPerformed += 1;
    return saved;
  };

  const writePartCreate = async (data) => {
    const step = {
      operation: "create",
      part_key: data.part_key,
      data,
    };
    partWritePlan.push(step);
    if (planOnly) return { ...data, id: `planned:${data.part_key}`, updated_date: "" };
    const { record: created, status } = await createBuilderPartWithRecovery({
      entity: staffEntities.BuilderPart,
      data,
      label: `Builder Part “${data.part_name || data.part_key || "Part"}” synchronization`,
    });
    if (status !== "existing") writesPerformed += 1;
    return created;
  };

  // (#419) Writes keep their per-row CAS guards — updateMany can't express a
  // different expected-state/patch per row — but they now run in a bounded
  // pool so a large sync doesn't spend N serial round-trips on the wire.
  // `synced` slots are reserved at queue time so result order stays
  // deterministic and matches descriptor order.
  const WRITE_CONCURRENCY = 4;
  const writeJobs = [];
  const queueWrite = (work) => {
    const slot = synced.length;
    synced.push(null);
    writeJobs.push(async () => {
      synced[slot] = await work();
    });
  };

  for (let index = 0; index < descriptors.length; index += 1) {
    const descriptor = descriptors[index];
    seen.add(descriptor.part_key);
    const old = byKey.get(descriptor.part_key);
    const resolvedEntity = findEntity(catalogs, descriptor.inventory_item_id, descriptor.inventory_entity);

    // Intentional Builder overrides are independent frozen Parts. Preserve the
    // override instead of allowing a Builder save to regenerate its values.
    if (old?.builder_sync_state === "detached_override") {
      const currentRow = findRow(catalogs, old.inventory_entity || resolvedEntity, old.inventory_item_id || descriptor.inventory_item_id);
      const candidateId = descriptor.inventory_item_id || old.inventory_item_id || old.original_inventory_item_id || "";
      const candidateEntity = findEntity(catalogs, candidateId, old.inventory_entity || resolvedEntity);
      const candidateRow = findRow(catalogs, candidateEntity, candidateId);
      const corePatch = {
        inventory_link_state: currentRow ? "attached" : old.inventory_link_state,
        current_inventory_snapshot: currentRow || old.current_inventory_snapshot || {},
        reattach_candidate_id: candidateId,
        reattach_candidate_name: rowName(candidateEntity, candidateRow) || old.inventory_item_name || descriptor.part_name,
        price_state: "detached",
        is_active: true,
      };
      if (!skipUnchangedWrites || patchDiffers(old, corePatch)) {
        const patch = { ...corePatch, last_price_check_at: syncNow() };
        queueWrite(() => writePartUpdate(old, patch));
      } else {
        synced.push(old);
      }
      detachedCount += 1;
      continue;
    }
    const currentRow = findRow(catalogs, resolvedEntity, descriptor.inventory_item_id);
    const currentName = rowName(resolvedEntity, currentRow) || descriptor.part_name;
    const oldFrozenName = old?.inventory_item_name || rowName(old?.inventory_entity, old?.frozen_inventory_snapshot) || descriptor.part_name;
    const candidate = !currentRow && oldFrozenName
      ? findNameCandidate(catalogs, old?.inventory_entity || resolvedEntity, oldFrozenName)
      : null;
    const hasInventoryLink = !!descriptor.inventory_item_id || !!old?.inventory_item_id || !!old?.original_inventory_item_id;
    const detached = hasInventoryLink && !currentRow;
    const currentPricing = pricingSnapshot(currentRow);
    const frozenPricing = pricingSnapshot(old?.frozen_inventory_snapshot);
    const linkChanged = !!old && !!descriptor.inventory_item_id && descriptor.inventory_item_id !== (old.inventory_item_id || old.original_inventory_item_id);
    const pricingChanged = !!old && !!currentRow && !same(currentPricing, frozenPricing);
    const changed = linkChanged || pricingChanged;
    const currentUnitCost = effectiveCurrentUnitCost(descriptor, currentRow);
    const currentExtended = num(descriptor.extended_cost);
    const timestamp = syncNow();

    const lastBuilderCalculatedPricing = old?.pricing_basis_snapshot?.builder_calculated_inventory_pricing || {};
    const builderAlreadyCalculatedCurrentPricing = !!old && same(currentPricing, lastBuilderCalculatedPricing);
    if (
      pricingChanged &&
      !legacyMode &&
      builderProduct.price_state !== "unchecked" &&
      !directLiveReprice &&
      !builderRecalculated &&
      !builderAlreadyCalculatedCurrentPricing
    ) {
      // A frozen inventory snapshot that differs from the current catalog means
      // the accepted price is stale. Non-live Builders must run their calculator
      // before Update Price unless we have explicit proof that this exact catalog
      // pricing was already used by the last Builder calculation.
      recalcRequired = true;
      recalcPartNames.push(currentName || descriptor.part_name);
    }

    let linkState = "manual";
    if (hasInventoryLink) {
      if (currentRow) linkState = "attached";
      else if (candidate) linkState = "reattach_available";
      else linkState = "detached";
    }

    if (detached) detachedCount += 1;
    if (changed) changedCount += 1;

    if (!old) {
      const establishBaseline = legacyMode || builderProduct.price_state === "unchecked" || acceptPrices;
      const initialFrozenUnit = establishBaseline ? (descriptor.unit_cost || currentUnitCost) : 0;
      const initialFrozenExtended = establishBaseline ? num(descriptor.extended_cost) : 0;
      if (!establishBaseline) {
        changedCount += 1;
        newPartCount += 1;
      }
      queueWrite(() => writePartCreate({
        builder_product_id: builderProduct.id,
        part_key: descriptor.part_key,
        sort_order: index,
        part_name: descriptor.part_name,
        part_type: descriptor.part_type,
        part_subtype: descriptor.part_subtype,
        source_module_key: builderProduct.module_key,
        source_path: descriptor.source_path,
        builder_sync_state: "linked",
        inventory_entity: resolvedEntity,
        inventory_item_id: descriptor.inventory_item_id,
        original_inventory_item_id: descriptor.inventory_item_id,
        inventory_item_name: currentName,
        inventory_link_state: linkState,
        reattach_candidate_id: candidate?.id || "",
        reattach_candidate_name: candidate ? rowName(old?.inventory_entity || resolvedEntity, candidate) : "",
        frozen_inventory_snapshot: establishBaseline ? (currentRow || {}) : {},
        current_inventory_snapshot: currentRow || {},
        builder_data: descriptor.builder_data,
        calculation_snapshot: descriptor.calculation_snapshot,
        pricing_basis_snapshot: {
          ...descriptor.pricing_basis_snapshot,
          inventory_pricing: currentPricing,
          ...(builderRecalculated ? { builder_calculated_inventory_pricing: currentPricing } : {}),
        },
        quantity: descriptor.quantity,
        unit: descriptor.unit,
        frozen_unit_cost: initialFrozenUnit,
        frozen_extended_cost: initialFrozenExtended,
        current_unit_cost: currentUnitCost,
        current_extended_cost: currentExtended,
        price_state: legacyMode
          ? "legacy_frozen"
          : detached
            ? "detached"
            : establishBaseline
              ? "current"
              : "changed",
        price_delta: currentExtended - initialFrozenExtended,
        price_delta_percent: initialFrozenExtended ? ((currentExtended - initialFrozenExtended) / initialFrozenExtended) * 100 : 0,
        inventory_updated_date_snapshot: establishBaseline ? (currentRow?.updated_date || "") : "",
        last_price_check_at: timestamp,
        last_price_update_at: acceptPrices ? timestamp : "",
        manual_cost_override: !hasInventoryLink,
        manual_cost: !hasInventoryLink ? descriptor.extended_cost : undefined,
        is_active: true,
        notes: legacyMode
          ? "Backfilled from an existing Builder Product. Saved estimator costs remain authoritative; catalog snapshot is compatibility context."
          : establishBaseline
            ? ""
            : "New Builder Part added after the Product price was frozen. Frozen cost remains $0 until Update Price is explicitly accepted.",
      }));
      continue;
    }

    const shouldAccept = acceptPrices && !detached;
    const frozenUnit = shouldAccept ? currentUnitCost : num(old.frozen_unit_cost, descriptor.unit_cost || currentUnitCost);
    const frozenExtended = shouldAccept ? currentExtended : num(old.frozen_extended_cost, descriptor.extended_cost);
    const state = detached
      ? "detached"
      : legacyMode || old.price_state === "legacy_frozen"
        ? "legacy_frozen"
        : changed || Math.abs(currentExtended - frozenExtended) > 0.005
          ? "changed"
          : "current";

    const patch = {
      sort_order: index,
      part_name: descriptor.part_name,
      part_type: descriptor.part_type,
      part_subtype: descriptor.part_subtype,
      source_module_key: builderProduct.module_key,
      source_path: descriptor.source_path,
      inventory_entity: resolvedEntity || old.inventory_entity,
      inventory_item_id: descriptor.inventory_item_id,
      inventory_item_name: currentName || old.inventory_item_name,
      inventory_link_state: linkState,
      reattach_candidate_id: candidate?.id || "",
      reattach_candidate_name: candidate ? rowName(old.inventory_entity || resolvedEntity, candidate) : "",
      current_inventory_snapshot: currentRow || {},
      builder_data: descriptor.builder_data,
      calculation_snapshot: descriptor.calculation_snapshot,
      pricing_basis_snapshot: {
        ...descriptor.pricing_basis_snapshot,
        inventory_pricing: currentPricing,
        builder_calculated_inventory_pricing: builderRecalculated
          ? currentPricing
          : old.pricing_basis_snapshot?.builder_calculated_inventory_pricing || {},
      },
      quantity: descriptor.quantity,
      unit: descriptor.unit,
      current_unit_cost: currentUnitCost,
      current_extended_cost: currentExtended,
      price_state: shouldAccept ? "current" : state,
      price_delta: currentExtended - frozenExtended,
      price_delta_percent: frozenExtended ? ((currentExtended - frozenExtended) / frozenExtended) * 100 : 0,
      is_active: true,
    };

    if (shouldAccept) {
      patch.frozen_inventory_snapshot = currentRow || old.frozen_inventory_snapshot || {};
      patch.frozen_unit_cost = frozenUnit;
      patch.frozen_extended_cost = frozenExtended;
      patch.inventory_updated_date_snapshot = currentRow?.updated_date || old.inventory_updated_date_snapshot || "";
      patch.last_price_update_at = timestamp;
    }

    if (!skipUnchangedWrites || patchDiffers(old, patch)) {
      const writePatch = { ...patch, last_price_check_at: timestamp };
      queueWrite(() => writePartUpdate(old, writePatch));
    } else {
      synced.push(old);
    }
  }

  // (#419) Manual add-ons each used to pay a serial inventory row read; fetch
  // the needed rows in one bounded parallel pre-pass before the update loop.
  const addonRowKeys = new Map();
  for (const old of existing || []) {
    if (seen.has(old.part_key) || old.is_active === false) continue;
    if (old.builder_sync_state !== "manual_addon") continue;
    if (!old.inventory_entity || !old.inventory_item_id || old.manual_cost_override) continue;
    const key = `${old.inventory_entity}:${old.inventory_item_id}`;
    if (!inventoryRowsOverride?.has(key) && !addonRowKeys.has(key)) addonRowKeys.set(key, old);
  }
  const addonRows = new Map();
  const addonKeys = [...addonRowKeys.keys()];
  for (let i = 0; i < addonKeys.length; i += WRITE_CONCURRENCY) {
    await Promise.all(addonKeys.slice(i, i + WRITE_CONCURRENCY).map(async (key) => {
      const part = addonRowKeys.get(key);
      try {
        addonRows.set(key, await staffEntities[part.inventory_entity].get(part.inventory_item_id));
      } catch (error) {
        if (strictCatalogs) {
          throw new Error(`${part.inventory_entity} inventory could not be verified for Part “${part.part_name || "Part"}”: ${error?.message || "read failed"}`);
        }
      }
    }));
  }

  for (const old of existing || []) {
    if (seen.has(old.part_key) || old.is_active === false) continue;
    if (old.builder_sync_state === "detached_override") {
      detachedCount += 1;
      synced.push(old);
      continue;
    }
    if (old.builder_sync_state === "manual_addon") {
      // Intentional independent add-ons are not produced by the Builder, but
      // they still track their own Master Inventory record for current-price
      // comparison and remain part of the Product economics on every Builder save.
      // Reserve the synced slot now; a queued refresh write overwrites it.
      const syncedSlot = synced.length;
      synced.push(old);
      if (old.inventory_entity && old.inventory_item_id && !old.manual_cost_override) {
        let currentRow = null;
        const inventoryKey = `${old.inventory_entity}:${old.inventory_item_id}`;
        if (inventoryRowsOverride?.has(inventoryKey)) {
          currentRow = inventoryRowsOverride.get(inventoryKey);
        } else {
          currentRow = addonRows.get(inventoryKey) || null;
        }
        if (currentRow) {
          const currentUnit = independentPartUnitCost(old, currentRow);
          const currentExtended = currentUnit * num(old.quantity, 1);
          const changed = Math.abs(currentExtended - num(old.frozen_extended_cost)) > 0.005 ||
            !same(pricingSnapshot(currentRow), pricingSnapshot(old.frozen_inventory_snapshot));
          const patch = {
            current_inventory_snapshot: currentRow,
            current_unit_cost: currentUnit,
            current_extended_cost: currentExtended,
            inventory_link_state: "attached",
            price_state: changed ? "changed" : "current",
            price_delta: currentExtended - num(old.frozen_extended_cost),
            price_delta_percent: num(old.frozen_extended_cost) ? ((currentExtended - num(old.frozen_extended_cost)) / num(old.frozen_extended_cost)) * 100 : 0,
            is_active: true,
          };
          if (changed) changedCount += 1;
          if (!skipUnchangedWrites || patchDiffers(old, patch)) {
            const writePatch = { ...patch, last_price_check_at: syncNow() };
            writeJobs.push(async () => { synced[syncedSlot] = await writePartUpdate(old, writePatch); });
          }
        } else {
          const patch = {
            inventory_link_state: "detached",
            price_state: "detached",
            is_active: true,
          };
          // This is an independent add-on, not a broken Builder-produced Part.
          // Keep the Part visibly detached and let Update Price block until the
          // user uses Switch Part, but do not trigger the Builder reattach modal.
          if (!skipUnchangedWrites || patchDiffers(old, patch)) {
            const writePatch = { ...patch, last_price_check_at: syncNow() };
            writeJobs.push(async () => { synced[syncedSlot] = await writePartUpdate(old, writePatch); });
          }
        }
      }
      continue;
    }
    const frozenRemovedCost = num(old.frozen_extended_cost);
    if (Math.abs(frozenRemovedCost) <= 0.005) {
      writeJobs.push(() => writePartUpdate(old, {
        is_active: false,
        current_unit_cost: 0,
        current_extended_cost: 0,
        price_state: "current",
        price_delta: 0,
        price_delta_percent: 0,
        last_price_check_at: syncNow(),
        notes: `${old.notes ? `${old.notes}\n` : ""}Part removed from Builder before it carried a frozen cost; historical row retained inactive.`,
      }));
      continue;
    }

    const alreadyPendingRemoval = !!old.builder_data?.[PENDING_REMOVAL_KEY];
    const removalNote = "Part no longer exists in the current Builder. Frozen cost is retained until Update Price accepts its removal.";
    const pendingRemoval = {
      current_unit_cost: 0,
      current_extended_cost: 0,
      price_state: "changed",
      price_delta: -frozenRemovedCost,
      price_delta_percent: -100,
      builder_data: { ...(old.builder_data || {}), [PENDING_REMOVAL_KEY]: true },
      is_active: true,
      notes: alreadyPendingRemoval
        ? (old.notes || removalNote)
        : `${old.notes ? `${old.notes}\n` : ""}${removalNote}`,
    };
    if (!skipUnchangedWrites || patchDiffers(old, pendingRemoval)) {
      const writePatch = { ...pendingRemoval, last_price_check_at: syncNow() };
      queueWrite(() => writePartUpdate(old, writePatch));
    } else {
      synced.push(old);
    }
    changedCount += 1;
    removedPartCount += 1;
  }

  // (#419) Drain the write queue through a bounded pool. Jobs start in
  // descriptor order (Promise.all invokes each chunk in order), so
  // partWritePlan keeps its deterministic order; per-row CAS is unchanged.
  for (let i = 0; i < writeJobs.length; i += WRITE_CONCURRENCY) {
    await Promise.all(writeJobs.slice(i, i + WRITE_CONCURRENCY).map((run) => run()));
  }

  const activeEconomicParts = synced.filter((part) => part.is_active !== false);
  const currentPartsTotal = activeEconomicParts.reduce(
    (sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)),
    0
  );
  const frozenPartsTotal = activeEconomicParts.reduce(
    (sum, part) => sum + num(part.frozen_extended_cost),
    0
  );
  const markupParts = activeEconomicParts.filter((part) => part.part_subtype === "markup");
  const currentMarkupTotal = markupParts.reduce(
    (sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)),
    0
  );
  const frozenMarkupTotal = markupParts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const manualAddons = activeEconomicParts.filter((part) => part.builder_sync_state === "manual_addon");
  const manualAddonFrozenTotal = manualAddons.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const manualAddonCurrentTotal = manualAddons.reduce((sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)), 0);
  const uniqueRecalcNames = [...new Set(recalcPartNames.filter(Boolean))];

  return {
    partCount: activeEconomicParts.length,
    detachedCount,
    changedCount,
    newPartCount,
    removedPartCount,
    writesPerformed,
    recalcRequired,
    recalcReason: recalcRequired
      ? `Master Inventory changed after this ${builderProduct.builder_name || "Builder"} was last calculated${uniqueRecalcNames.length ? `: ${uniqueRecalcNames.slice(0, 4).join(", ")}${uniqueRecalcNames.length > 4 ? "…" : ""}` : ""}. Reopen and save the Builder before accepting Update Price.`
      : "",
    usesDirectLiveReprice: directLiveReprice && !legacyMode,
    currentPartsTotal,
    frozenPartsTotal,
    currentMarkupTotal,
    frozenMarkupTotal,
    manualAddonFrozenTotal,
    manualAddonCurrentTotal,
    parts: synced,
    partWritePlan,
  };
}

function assertUniqueBuilderPartKeys(parts, builderProductId, label = "Builder Parts") {
  if (!Array.isArray(parts)) throw new Error(`${label} could not be verified while recovering a Builder mutation.`);
  const seen = new Map();
  for (const part of parts) {
    if (String(part?.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error(`${label} contains a Part owned by a different Builder Product. Recovery stopped before continuing.`);
    }
    const key = String(part?.part_key || "").trim();
    if (!key) continue;
    if (seen.has(key)) {
      throw new Error(`${label} contains multiple Parts with key “${key}” for the same Builder Product. Recovery stopped without choosing between duplicate Parts.`);
    }
    seen.set(key, part.id || "");
  }
  return true;
}

export async function applyBuilderPartPriceAcceptancePlan(builderProductId, plan, { partsOverride = undefined } = {}) {
  const parts = partsOverride !== undefined
    ? partsOverride
    : await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" });
  assertUniqueBuilderPartKeys(parts, builderProductId);
  const byId = new Map(parts.map((part) => [part.id, part]));
  const byKey = new Map(parts.map((part) => [part.part_key, part]));
  let writesPerformed = 0;
  let createdAny = false;

  for (const step of plan?.part_updates || []) {
    if (step.operation === "create") {
      const data = step.data || {};
      const existing = byKey.get(step.part_key || data.part_key);
      if (existing) {
        if (existing.builder_product_id !== builderProductId) {
          throw new Error("A planned Builder Part key is now owned by a different Product. Reload before continuing.");
        }
        if (patchDiffers(existing, data)) {
          throw new Error(`Part “${existing.part_name || "Part"}” appeared while the Builder mutation was pending with different data. No unrelated Part was overwritten.`);
        }
        continue;
      }
      const { record: created, status } = await createBuilderPartWithRecovery({
        entity: staffEntities.BuilderPart,
        data,
        label: `Builder Part “${data.part_name || data.part_key || "Part"}” recovery create`,
      });
      if (status !== "existing") {
        writesPerformed += 1;
        createdAny = true;
      }
      if (created?.id) byId.set(created.id, created);
      if (created?.part_key) byKey.set(created.part_key, created);
      continue;
    }

    const part = byId.get(step.part_id);
    if (!part || part.builder_product_id !== builderProductId) {
      throw new Error("A Builder Part changed ownership while a Builder mutation was pending. Reload before continuing.");
    }
    const targetPatch = step.patch || {};
    if (!patchDiffers(part, targetPatch)) continue;
    const expected = String(step.expected_updated_date || "").trim();
    const current = String(part.updated_date || "").trim();
    if (expected && current && current !== expected) {
      throw new Error(`Part “${part.part_name || "Part"}” changed while a Builder mutation was pending. No unrelated Part edit was overwritten.`);
    }
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderPart,
      id: part.id,
      expectedUpdatedAt: part.updated_date || "",
      expectedFields: expectedBuilderEntityFields(part, targetPatch),
      nextFields: targetPatch,
      guardFields: { builder_product_id: builderProductId },
      label: `Builder Part “${part.part_name || "Part"}” recovery update`,
    });
    writesPerformed += 1;
  }

  if (createdAny) {
    const verifiedParts = await loadAllEntityRows({
      entity: staffEntities.BuilderPart,
      query: { builder_product_id: builderProductId },
      sort: "sort_order",
      label: "Builder Parts post-create verification",
    });
    assertUniqueBuilderPartKeys(verifiedParts, builderProductId, "Builder Parts post-create verification");
  }

  return { writesPerformed };
}

export async function acceptBuilderPartPrices(builderProductId, {
  builderOverride = undefined,
  partsOverride = undefined,
  apply = true,
  timestamp = nowIso(),
} = {}) {
  const [parts, builder] = await Promise.all([
    partsOverride !== undefined
      ? Promise.resolve(partsOverride)
      : loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" }),
    builderOverride !== undefined
      ? Promise.resolve(builderOverride)
      : staffEntities.BuilderProduct.get(builderProductId),
  ]);
  if (!builder?.id || builder.id !== builderProductId) {
    throw new Error("Builder Product could not be verified before accepting Part prices.");
  }
  if (!Array.isArray(parts)) {
    throw new Error("Builder Parts could not be verified before accepting pricing.");
  }
  if (parts.some((part) => part?.builder_product_id !== builderProductId)) {
    throw new Error("Builder Part ownership changed before pricing could be accepted. Reload the estimate and try again.");
  }
  const activeParts = parts.filter((row) => row.is_active !== false);
  const detachedParts = activeParts.filter((part) =>
    part.builder_sync_state === "detached_override" ||
    ["detached", "reattach_available"].includes(part.inventory_link_state)
  );

  // All-or-nothing guard: do not mutate even one Part while any linked Part is
  // detached. The user must resolve/reattach those Parts first.
  if (detachedParts.length > 0) {
    return {
      changedParts: [],
      detachedCount: detachedParts.length,
      detachedParts: detachedParts.map((part) => ({
        part_id: part.id,
        part_key: part.part_key,
        part_name: part.part_name,
        inventory_item_name: part.inventory_item_name,
        reattach_candidate_id: part.reattach_candidate_id || "",
        reattach_candidate_name: part.reattach_candidate_name || "",
      })),
    };
  }

  const staleCatalogParts = !builder || DIRECT_LIVE_REPRICE_MODULES.has(builder.module_key) || builder.price_state === "unchecked"
    ? []
    : activeParts.filter((part) => {
        if (["manual", "manual_addon", "detached_override"].includes(part.builder_sync_state)) return false;
        const currentPricing = pricingSnapshot(part.current_inventory_snapshot);
        const frozenPricing = pricingSnapshot(part.frozen_inventory_snapshot);
        if (same(currentPricing, frozenPricing)) return false;
        const builderCalculatedPricing = part.pricing_basis_snapshot?.builder_calculated_inventory_pricing || {};
        // Frozen pricing may intentionally differ after the Builder has been
        // recalculated. That is exactly the state Update Price is meant to accept.
        // Block only when the current catalog differs from BOTH the frozen price
        // and the pricing explicitly used by the last Builder calculation.
        return !same(currentPricing, builderCalculatedPricing);
      });

  if (builder?.price_recalc_required || staleCatalogParts.length > 0) {
    return {
      changedParts: [],
      detachedCount: 0,
      detachedParts: [],
      recalcRequired: true,
      recalcParts: staleCatalogParts.map((part) => ({
        part_id: part.id,
        part_key: part.part_key,
        part_name: part.part_name,
        inventory_item_name: part.inventory_item_name,
      })),
      recalcReason: builder?.price_recalc_reason || "Master Inventory changed after this Builder was last calculated. Reopen and save the Builder before accepting Update Price.",
    };
  }

  const changedParts = [];
  const partUpdates = [];
  let activePartCount = 0;

  for (const part of activeParts) {
    const wasChanged = part.price_state === "changed" ||
      Math.abs(num(part.current_extended_cost) - num(part.frozen_extended_cost)) > 0.005 ||
      !same(pricingSnapshot(part.current_inventory_snapshot), pricingSnapshot(part.frozen_inventory_snapshot));
    const pendingRemoval = !!part.builder_data?.[PENDING_REMOVAL_KEY];
    if (wasChanged) {
      changedParts.push({
        part_id: part.id,
        part_key: part.part_key,
        part_name: part.part_name,
        previous_inventory_item_id: part.original_inventory_item_id || part.inventory_item_id,
        current_inventory_item_id: part.inventory_item_id,
        previous_unit_cost: num(part.frozen_unit_cost),
        new_unit_cost: num(part.current_unit_cost),
        previous_extended_cost: num(part.frozen_extended_cost),
        new_extended_cost: num(part.current_extended_cost),
        previous_inventory_snapshot: part.frozen_inventory_snapshot || {},
        new_inventory_snapshot: part.current_inventory_snapshot || {},
        action: pendingRemoval
          ? "remove"
          : Math.abs(num(part.frozen_extended_cost)) <= 0.005 && Math.abs(num(part.current_extended_cost)) > 0.005
            ? "add"
            : "price_update",
      });
    }
    const acceptedBuilderData = { ...(part.builder_data || {}) };
    delete acceptedBuilderData[PENDING_REMOVAL_KEY];
    partUpdates.push({
      part_id: part.id,
      expected_updated_date: part.updated_date || "",
      patch: {
        frozen_inventory_snapshot: part.current_inventory_snapshot || part.frozen_inventory_snapshot || {},
        frozen_unit_cost: num(part.current_unit_cost, num(part.frozen_unit_cost)),
        frozen_extended_cost: num(part.current_extended_cost, num(part.frozen_extended_cost)),
        inventory_updated_date_snapshot: part.current_inventory_snapshot?.updated_date || part.inventory_updated_date_snapshot || "",
        price_state: "current",
        price_delta: 0,
        price_delta_percent: 0,
        builder_data: acceptedBuilderData,
        is_active: !pendingRemoval,
        last_price_update_at: timestamp,
      },
    });
    if (!pendingRemoval) activePartCount += 1;
  }

  const acceptancePlan = {
    timestamp,
    part_updates: partUpdates,
    changed_parts: changedParts,
    active_part_count: activePartCount,
  };
  if (apply) {
    await applyBuilderPartPriceAcceptancePlan(builderProductId, acceptancePlan, { partsOverride: parts });
  }

  return {
    changedParts,
    detachedCount: 0,
    detachedParts: [],
    recalcRequired: false,
    recalcParts: [],
    recalcReason: "",
    activePartCount,
    acceptancePlan,
  };
}

export async function getDetachedBuilderParts(builderProductId) {
  if (!builderProductId) return [];
  const parts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" });
  return (parts || [])
    .filter(requiresBuilderReattach)
    .sort((a, b) => num(a.sort_order) - num(b.sort_order))
    .map((part) => ({
      ...part,
      can_reattach: part.builder_sync_state === "detached_override" || !!part.reattach_candidate_id,
    }));
}

function assertEstimatorPartVersion(part, expectedUpdatedAt = "") {
  const expected = String(expectedUpdatedAt || "").trim();
  const current = String(part?.updated_date || "").trim();
  if (expected && current !== expected) {
    throw new Error(`Part “${part?.part_name || "Part"}” changed in another session. Reload the Product before continuing.`);
  }
}

function estimateBuilderLine(estimate, builderProductId) {
  return (estimate?.line_items || []).find((line) => line.builder_product_id === builderProductId) || null;
}

async function loadPendingAwarePartMutationContext(partId, options = {}, allowedKinds = []) {
  const part = await staffEntities.BuilderPart.get(partId);
  if (!part?.id) throw new Error("The Part could not be loaded.");
  const builder = await staffEntities.BuilderProduct.get(part.builder_product_id);
  if (!builder?.id || !builder.estimate_id) throw new Error("The Builder Product could not be verified against an estimate.");
  const estimate = await staffEntities.AllInOneEstimate.get(builder.estimate_id);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const line = estimateBuilderLine(estimate, builder.id);
  if (!line) throw new Error("This Product is no longer part of the estimate. Reload before changing its Parts.");

  const pending = pendingBuilderMutation(line);
  if (pending) {
    if (!allowedKinds.includes(pending.kind) || String(pending.target_part_id || "") !== String(part.id)) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before changing this Part.");
    }
    await assertEstimateProductMutationAllowed(estimate, { allowPriceAcceptanceKey: pending.key });
    return { part, builder, estimate, line, pending, alreadyComplete: false };
  }

  if (typeof options.isAlreadyComplete === "function" && options.isAlreadyComplete({ part, builder, estimate, line })) {
    return { part, builder, estimate, line, pending: null, alreadyComplete: true };
  }

  assertEstimatorPartVersion(part, options.expectedPartUpdatedAt || "");
  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: options.expectedEstimateUpdatedAt || "" });
  return { part, builder, estimate, line, pending: null, alreadyComplete: false };
}

export async function detachBuilderPartOverride(partId, reason = "Detached for independent Part override.", options = {}) {
  if (!partId) return null;
  const context = await loadPendingAwarePartMutationContext(
    partId,
    {
      ...options,
      isAlreadyComplete: ({ part }) => part.builder_sync_state === "detached_override",
    },
    ["builder_detach_override"]
  );
  const { part, builder, estimate, line, pending, alreadyComplete } = context;

  if (pending) {
    const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
    await resumeBuilderMutation({
      estimateId: estimate.id,
      estimate,
      builder,
      parts: allParts,
      line,
      pending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    const step = (pending.part_acceptance_plan?.part_updates || []).find((item) => item.part_id === part.id);
    return { ...part, ...(step?.patch || {}) };
  }
  if (alreadyComplete) return part;
  if (["manual", "manual_addon"].includes(part.builder_sync_state)) {
    throw new Error("Independent manual Parts do not need to be detached from a Builder.");
  }

  const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
  if (!Array.isArray(allParts) || allParts.some((row) => row?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified before detaching this Part.");
  }
  const detachedCount = allParts.filter((row) =>
    row.id === part.id ? row.is_active !== false : requiresBuilderReattach(row)
  ).length;
  const timestamp = nowIso();
  const detachedSnapshot = {
    part_name: part.part_name,
    client_label: part.client_label,
    quantity: part.quantity,
    unit: part.unit,
    inventory_entity: part.inventory_entity,
    inventory_item_id: part.inventory_item_id,
    inventory_item_name: part.inventory_item_name,
    frozen_unit_cost: num(part.frozen_unit_cost),
    frozen_extended_cost: num(part.frozen_extended_cost),
    builder_data: part.builder_data || {},
    calculation_snapshot: part.calculation_snapshot || {},
    pricing_basis_snapshot: part.pricing_basis_snapshot || {},
    detail_overrides: part.detail_overrides || {},
    source_path: part.source_path,
  };
  const me = await base44.auth.me().catch(() => null);
  const detachedBy = String(options.detachedBy || me?.full_name || me?.email || "").trim();
  const partPatch = {
    builder_sync_state: "detached_override",
    builder_detached_at: timestamp,
    builder_detached_reason: reason,
    builder_detached_by: detachedBy,
    builder_detached_snapshot: detachedSnapshot,
    reattach_candidate_id: part.inventory_item_id || part.original_inventory_item_id || "",
    reattach_candidate_name: part.inventory_item_name || part.part_name || "",
    price_state: "detached",
    last_price_check_at: timestamp,
    notes: `${part.notes ? `${part.notes}\n` : ""}Detached from Builder for independent override. Frozen pricing retained.`,
  };
  const changedParts = [{
    part_id: part.id,
    part_key: part.part_key,
    part_name: part.part_name,
    action: "detach_override",
    frozen_unit_cost: num(part.frozen_unit_cost),
    frozen_extended_cost: num(part.frozen_extended_cost),
    inventory_item_id: part.inventory_item_id || "",
    source_path: part.source_path || "",
  }];
  const builderPatch = {
    detached_part_count: detachedCount,
    needs_reattach_review: true,
    price_state: "detached_parts",
    last_price_check_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    detached_part_count: detachedCount,
    needs_reattach_review: true,
    price_state: "detached_parts",
    last_price_check_at: timestamp,
  };
  const revision = {
    builder_product_id: builder.id,
    estimate_id: builder.estimate_id || "",
    reason: "manual_adjustment",
    previous_total_cost: num(builder.frozen_cost),
    new_total_cost: num(builder.frozen_cost),
    previous_customer_price: num(builder.frozen_customer_price, num(builder.frozen_cost)),
    new_customer_price: num(builder.frozen_customer_price, num(builder.frozen_cost)),
    changed_parts: changedParts,
    builder_snapshot_before: builder.builder_snapshot || {},
    builder_snapshot_after: builder.builder_snapshot || {},
    price_snapshot_before: { total: num(builder.frozen_cost), pricing_accepted: false },
    price_snapshot_after: { total: num(builder.frozen_cost), pricing_accepted: false },
    notes: reason,
  };
  const operationKey = `builder_detach_override:${builder.id}:${part.id}:${num(builder.builder_version, 1)}:${builderMutationHash({
    estimate_updated_date: estimate.updated_date || "",
    part_updated_date: part.updated_date || "",
    reason,
    part_patch: partPatch,
  })}`;
  const recoveryMarker = {
    key: operationKey,
    kind: "builder_detach_override",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_id: part.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    part_acceptance_plan: {
      timestamp,
      part_updates: [{ part_id: part.id, expected_updated_date: part.updated_date || "", patch: partPatch }],
      changed_parts: changedParts,
      active_part_count: allParts.filter((row) => row.is_active !== false).length,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision,
  };

  const marked = await markBuilderMutationPending({ estimate, builder, line, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
  return { ...part, ...partPatch };
}

function detachedOverrideChangesAlreadyApplied(part, changes = {}) {
  if (part?.builder_sync_state !== "detached_override") return false;
  if (changes.part_name !== undefined && String(part.part_name || "") !== String(changes.part_name || "Part")) return false;
  if (changes.client_label !== undefined && String(part.client_label || "") !== String(changes.client_label || "")) return false;
  if (changes.quantity !== undefined && Math.abs(num(part.quantity) - Math.max(0, num(changes.quantity))) > 0.000001) return false;
  if (changes.unit !== undefined && String(part.unit || "") !== String(changes.unit || "")) return false;
  if (changes.frozen_unit_cost !== undefined && Math.abs(num(part.frozen_unit_cost) - num(changes.frozen_unit_cost)) > 0.000001) return false;
  if (changes.detail_overrides !== undefined && !same(part.detail_overrides || {}, changes.detail_overrides || {})) return false;
  if (changes.notes !== undefined && String(part.notes || "") !== String(changes.notes || "")) return false;
  if (changes.manual_cost_override_reason !== undefined && String(part.manual_cost_override_reason || "") !== String(changes.manual_cost_override_reason || "")) return false;
  return true;
}

export async function updateDetachedPartOverride(partId, changes = {}, options = {}) {
  const context = await loadPendingAwarePartMutationContext(
    partId,
    {
      ...options,
      isAlreadyComplete: ({ part }) => detachedOverrideChangesAlreadyApplied(part, changes),
    },
    ["builder_detached_override_update"]
  );
  const { part, builder, estimate, line, pending, alreadyComplete } = context;

  if (pending) {
    const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
    await resumeBuilderMutation({
      estimateId: estimate.id,
      estimate,
      builder,
      parts: allParts,
      line,
      pending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    const step = (pending.part_acceptance_plan?.part_updates || []).find((item) => item.part_id === part.id);
    return { ...part, ...(step?.patch || {}) };
  }
  if (alreadyComplete) return part;
  if (part.builder_sync_state !== "detached_override") {
    throw new Error("This Part must be detached from its Builder before it can be overridden independently.");
  }

  const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
  if (!Array.isArray(allParts) || allParts.some((row) => row?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified before updating this detached override.");
  }
  const previousExtended = num(part.frozen_extended_cost);
  const quantity = changes.quantity !== undefined ? Math.max(0, num(changes.quantity)) : num(part.quantity, 1);
  const frozenUnitCost = changes.frozen_unit_cost !== undefined ? num(changes.frozen_unit_cost) : num(part.frozen_unit_cost);
  const nextExtended = quantity * frozenUnitCost;
  const delta = nextExtended - previousExtended;
  const timestamp = nowIso();
  const previousDetailOverrides = part.detail_overrides || {};
  const nextDetailOverrides = changes.detail_overrides !== undefined ? { ...(changes.detail_overrides || {}) } : previousDetailOverrides;
  const partPatch = {
    part_name: changes.part_name !== undefined ? String(changes.part_name || "Part") : part.part_name,
    client_label: changes.client_label !== undefined ? String(changes.client_label || "") : part.client_label,
    quantity,
    unit: changes.unit !== undefined ? String(changes.unit || "") : part.unit,
    frozen_unit_cost: frozenUnitCost,
    frozen_extended_cost: nextExtended,
    current_unit_cost: frozenUnitCost,
    current_extended_cost: nextExtended,
    manual_cost_override: true,
    manual_cost: nextExtended,
    manual_cost_override_reason: changes.manual_cost_override_reason !== undefined ? String(changes.manual_cost_override_reason || "") : String(part.manual_cost_override_reason || ""),
    detail_overrides: nextDetailOverrides,
    price_state: "detached",
    price_delta: 0,
    price_delta_percent: 0,
    notes: changes.notes !== undefined ? String(changes.notes || "") : part.notes,
    last_price_update_at: timestamp,
    last_price_check_at: timestamp,
  };

  const previousProductCost = num(builder.frozen_cost);
  const nextProductCost = previousProductCost + delta;
  const previousCustomerPrice = num(builder.frozen_customer_price, previousProductCost);
  const nextCustomerPrice = previousCustomerPrice + delta;
  const changedParts = [{
    part_id: part.id,
    part_key: part.part_key,
    part_name: partPatch.part_name,
    action: "override_update",
    previous_quantity: num(part.quantity, 1),
    new_quantity: quantity,
    previous_unit: part.unit || "",
    new_unit: partPatch.unit || "",
    previous_unit_cost: num(part.frozen_unit_cost),
    new_unit_cost: frozenUnitCost,
    previous_extended_cost: previousExtended,
    new_extended_cost: nextExtended,
    delta,
    previous_detail_overrides: previousDetailOverrides,
    new_detail_overrides: nextDetailOverrides,
  }];
  const builderPatch = {
    frozen_cost: nextProductCost,
    frozen_customer_price: nextCustomerPrice,
    price_state: "detached_parts",
    needs_reattach_review: true,
    last_price_update_at: timestamp,
    last_price_update_note: `Independent override updated for ${partPatch.part_name}.`,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    total_snapshot: num(line.total_snapshot, previousProductCost) + delta,
    customer_price_snapshot: acceptedCustomerUnitPrice(line) + delta,
    live_customer_price_snapshot: liveCustomerUnitPrice(line) + delta,
    price_state: "detached_parts",
    needs_reattach_review: true,
    last_price_update_at: timestamp,
    last_price_check_at: timestamp,
  };
  const revision = {
    builder_product_id: builder.id,
    estimate_id: builder.estimate_id || "",
    reason: "manual_adjustment",
    previous_total_cost: previousProductCost,
    new_total_cost: nextProductCost,
    previous_customer_price: previousCustomerPrice,
    new_customer_price: nextCustomerPrice,
    changed_parts: changedParts,
    builder_snapshot_before: builder.builder_snapshot || {},
    builder_snapshot_after: builder.builder_snapshot || {},
    price_snapshot_before: { total: previousProductCost, detached_override: true },
    price_snapshot_after: { total: nextProductCost, detached_override: true },
    notes: "Independent detached Part override updated. Builder synchronization remains disabled for this Part.",
  };
  const operationKey = `builder_detached_override_update:${builder.id}:${part.id}:${num(builder.builder_version, 1)}:${builderMutationHash({
    estimate_updated_date: estimate.updated_date || "",
    part_updated_date: part.updated_date || "",
    changes,
    next_product_cost: nextProductCost,
    next_customer_price: nextCustomerPrice,
  })}`;
  const recoveryMarker = {
    key: operationKey,
    kind: "builder_detached_override_update",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_id: part.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    part_acceptance_plan: {
      timestamp,
      part_updates: [{ part_id: part.id, expected_updated_date: part.updated_date || "", patch: partPatch }],
      changed_parts: changedParts,
      active_part_count: allParts.filter((row) => row.is_active !== false).length,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision,
  };

  const marked = await markBuilderMutationPending({ estimate, builder, line, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
  return { ...part, ...partPatch };
}

function pathTokens(path) {
  return String(path || "")
    .replace(/\[(\d+)\]/g, ".$1")
    .split(".")
    .map((token) => token.trim())
    .filter(Boolean);
}

function setAtPath(target, path, value) {
  const tokens = pathTokens(path);
  if (!tokens.length) return false;
  let cursor = target;
  for (let i = 0; i < tokens.length - 1; i += 1) {
    const token = tokens[i];
    if (cursor?.[token] === undefined || cursor?.[token] === null) return false;
    cursor = cursor[token];
  }
  const last = tokens[tokens.length - 1];
  if (!cursor || typeof cursor !== "object") return false;
  cursor[last] = value;

  // Channel Letter / Maintenance history contains both inventory_id and
  // inventory_item_id generations. Keep an existing alias synchronized so the
  // old and new calculator/editor paths continue to agree after reattachment.
  if (last === "inventory_item_id" && Object.prototype.hasOwnProperty.call(cursor, "inventory_id")) {
    cursor.inventory_id = value;
  } else if (last === "inventory_id" && Object.prototype.hasOwnProperty.call(cursor, "inventory_item_id")) {
    cursor.inventory_item_id = value;
  }
  return true;
}

function topLevelField(path) {
  return pathTokens(path)[0] || "";
}

export async function reattachBuilderParts({ builderProductId, partIds = [], expectedEstimateUpdatedAt = "", expectedPartVersions = {} }) {
  if (!builderProductId || !partIds.length) {
    return { reattached: [], remainingDetached: await getDetachedBuilderParts(builderProductId) };
  }

  const builder = await staffEntities.BuilderProduct.get(builderProductId);
  if (!builder?.id || !builder.estimate_id) throw new Error("The Builder Product could not be verified against an estimate.");
  const estimate = await staffEntities.AllInOneEstimate.get(builder.estimate_id);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const line = estimateBuilderLine(estimate, builder.id);
  if (!line) throw new Error("This Product is no longer part of the estimate. Reload before reattaching Parts.");

  const existingPending = pendingBuilderMutation(line);
  if (existingPending) {
    if (existingPending.kind !== "builder_reattach_parts" || String(existingPending.builder_product_id || "") !== String(builder.id)) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before reattaching Parts.");
    }
    const currentParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
    await resumeBuilderMutation({
      estimateId: estimate.id,
      estimate,
      builder,
      parts: currentParts,
      line,
      pending: existingPending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    return {
      reattached: existingPending.revision?.changed_parts || [],
      remainingDetached: await getDetachedBuilderParts(builder.id),
      builderProject: existingPending.patched_source || null,
      recovered: true,
    };
  }

  const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
  if (!Array.isArray(allParts) || allParts.some((part) => part?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified before reattachment.");
  }
  const requestedIds = new Set(partIds);
  const requestedParts = allParts.filter((part) => requestedIds.has(part.id));
  if (requestedParts.length !== requestedIds.size) {
    throw new Error("One or more selected Parts no longer belong to this Product. Reload before reattaching.");
  }

  // A lost final response leaves the browser with stale Part versions even though
  // the server already completed the requested reattachment. Treat that verified
  // server state as a no-op rather than creating another reattach revision.
  if (requestedParts.every((part) => !requiresBuilderReattach(part))) {
    return {
      reattached: requestedParts.map((part) => ({ part_id: part.id, part_key: part.part_key, part_name: part.part_name })),
      remainingDetached: await getDetachedBuilderParts(builder.id),
      builderProject: builder.source_entity && builder.source_project_id
        ? await staffEntities[builder.source_entity].get(builder.source_project_id).catch(() => null)
        : null,
      alreadyCompleted: true,
    };
  }

  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  requestedParts.forEach((part) => assertEstimatorPartVersion(part, expectedPartVersions?.[part.id] || ""));

  if (!builder.source_entity || !builder.source_project_id) {
    throw new Error("This Builder no longer has an editable source project to reattach Parts to.");
  }

  const [source, catalogs] = await Promise.all([
    staffEntities[builder.source_entity].get(builder.source_project_id),
    loadBuilderCatalogs(builder.module_key, { strict: true }),
  ]);
  if (!source) throw new Error("The Builder source project could not be loaded.");

  const detached = allParts
    .filter(requiresBuilderReattach)
    .sort((a, b) => num(a.sort_order) - num(b.sort_order))
    .map((part) => ({ ...part, can_reattach: part.builder_sync_state === "detached_override" || !!part.reattach_candidate_id }));
  const selected = detached.filter((part) => requestedIds.has(part.id));
  if (selected.length !== requestedIds.size) {
    throw new Error("One or more selected Parts changed or are no longer detached. Reload the Product before reattaching.");
  }

  const beforeSnapshot = builder.builder_snapshot || source;
  const patchedSource = JSON.parse(JSON.stringify(source));
  const changedRoots = new Set();
  const reattached = [];
  const selectedPatches = new Map();

  for (const part of selected) {
    const builderOverride = part.builder_sync_state === "detached_override";
    if (builderOverride) {
      selectedPatches.set(part.id, {
        builder_sync_state: "linked",
        builder_detached_at: "",
        builder_detached_reason: "",
        builder_detached_by: "",
        detail_overrides: {},
        price_state: "changed",
      });
    } else {
      if (!part.reattach_candidate_id) throw new Error(`Part “${part.part_name || "Part"}” no longer has a verified reattach candidate.`);
      const candidateEntity = findEntity(catalogs, part.reattach_candidate_id, part.inventory_entity || "");
      const candidateRow = findRow(catalogs, candidateEntity, part.reattach_candidate_id);
      if (!candidateEntity || !candidateRow) {
        throw new Error(`The replacement Master Inventory record for Part “${part.part_name || "Part"}” could not be verified.`);
      }
      const changed = setAtPath(patchedSource, part.source_path, part.reattach_candidate_id);
      if (!changed) throw new Error(`Part “${part.part_name || "Part"}” could not be mapped back into the current Builder source record.`);
      const root = topLevelField(part.source_path);
      if (root) changedRoots.add(root);
      selectedPatches.set(part.id, { detail_overrides: {} });
    }
    reattached.push({
      part_id: part.id,
      part_key: part.part_key,
      part_name: part.part_name,
      reattach_type: builderOverride ? "builder_override" : "inventory_replacement",
      previous_inventory_item_id: part.inventory_item_id || part.original_inventory_item_id || "",
      current_inventory_item_id: part.reattach_candidate_id || part.inventory_item_id || "",
      previous_inventory_name: part.inventory_item_name || "",
      current_inventory_name: part.reattach_candidate_name || part.inventory_item_name || "",
      frozen_unit_cost: num(part.frozen_unit_cost),
      frozen_extended_cost: num(part.frozen_extended_cost),
      cleared_detail_overrides: part.detail_overrides || {},
      source_path: part.source_path,
    });
  }

  const sourcePatch = {};
  changedRoots.forEach((root) => { sourcePatch[root] = patchedSource[root]; });

  const inventoryRowsOverride = new Map();
  for (const part of allParts) {
    if (part.builder_sync_state !== "manual_addon" || !part.inventory_entity || !part.inventory_item_id || part.manual_cost_override) continue;
    const row = await staffEntities[part.inventory_entity].get(part.inventory_item_id);
    if (!row) throw new Error(`${part.inventory_entity} inventory could not be verified for Part “${part.part_name || "Part"}”.`);
    inventoryRowsOverride.set(`${part.inventory_entity}:${part.inventory_item_id}`, row);
  }
  const existingPartsForSync = allParts.map((part) =>
    selectedPatches.has(part.id) ? { ...part, ...selectedPatches.get(part.id) } : part
  );

  const timestamp = nowIso();
  const plannedSummary = await syncBuilderParts({
    builderProduct: builder,
    sourceProject: patchedSource,
    acceptPrices: false,
    legacyMode: false,
    catalogsOverride: catalogs,
    strictCatalogs: true,
    existingPartsOverride: existingPartsForSync,
    inventoryRowsOverride,
    planOnly: true,
    planTimestamp: timestamp,
  });
  const plannedPartUpdates = (plannedSummary.partWritePlan || []).map((step) =>
    step.operation !== "create" && selectedPatches.has(step.part_id)
      ? { ...step, patch: { ...selectedPatches.get(step.part_id), ...(step.patch || {}) } }
      : step
  );
  const remainingDetached = (plannedSummary.parts || [])
    .filter(requiresBuilderReattach)
    .sort((a, b) => num(a.sort_order) - num(b.sort_order))
    .map((part) => ({
      ...part,
      can_reattach: part.builder_sync_state === "detached_override" || !!part.reattach_candidate_id,
    }));

  const builderPatch = {
    builder_snapshot: patchedSource,
    builder_snapshot_at: timestamp,
    builder_snapshot_source_updated_date: timestamp,
    part_count: plannedSummary.partCount,
    detached_part_count: remainingDetached.length,
    needs_reattach_review: remainingDetached.length > 0,
    price_state: remainingDetached.length > 0 ? "detached_parts" : "changed",
    last_price_check_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    detached_part_count: remainingDetached.length,
    needs_reattach_review: remainingDetached.length > 0,
    price_state: remainingDetached.length > 0 ? "detached_parts" : "changed",
    last_price_check_at: timestamp,
  };
  const revision = {
    builder_product_id: builder.id,
    estimate_id: builder.estimate_id || "",
    reason: "reattach",
    previous_total_cost: num(builder.frozen_cost),
    new_total_cost: num(builder.frozen_cost),
    previous_customer_price: num(builder.frozen_customer_price, num(builder.frozen_cost)),
    new_customer_price: num(builder.frozen_customer_price, num(builder.frozen_cost)),
    changed_parts: reattached,
    builder_snapshot_before: beforeSnapshot,
    builder_snapshot_after: patchedSource,
    price_snapshot_before: { total: num(builder.frozen_cost), pricing_accepted: false },
    price_snapshot_after: { total: num(builder.frozen_cost), pricing_accepted: false },
    notes: `Reattached ${reattached.length} Part${reattached.length === 1 ? "" : "s"}. Frozen pricing was preserved; a separate Update Price action is required to accept recalculated pricing.`,
  };
  const operationKey = `builder_reattach_parts:${builder.id}:${num(builder.builder_version, 1)}:${builderMutationHash({
    estimate_updated_date: estimate.updated_date || "",
    source_updated_date: source.updated_date || "",
    selected_parts: selected.map((part) => ({ id: part.id, updated_date: part.updated_date || "", candidate: part.reattach_candidate_id || "", state: part.builder_sync_state })),
    source_patch: sourcePatch,
    part_updates: plannedPartUpdates,
  })}`;
  const recoveryMarker = {
    key: operationKey,
    kind: "builder_reattach_parts",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_ids: selected.map((part) => part.id),
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    source_entity: builder.source_entity,
    source_project_id: builder.source_project_id,
    source_updated_date_before: source.updated_date || "",
    source_patch: sourcePatch,
    patched_source: patchedSource,
    part_acceptance_plan: {
      timestamp,
      part_updates: plannedPartUpdates,
      changed_parts: reattached,
      active_part_count: plannedSummary.partCount,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision,
  };

  // Re-read the source immediately before taking the durable Estimate marker so
  // a pre-existing concurrent source edit aborts before any recovery state exists.
  const latestSource = await staffEntities[builder.source_entity].get(builder.source_project_id);
  if (!latestSource) throw new Error("The Builder source project could not be verified before starting reattachment.");
  if (source.updated_date && latestSource.updated_date && source.updated_date !== latestSource.updated_date) {
    throw new Error("The Builder source project changed in another session before reattachment started. No source or Part changes were written.");
  }

  const marked = await markBuilderMutationPending({ estimate, builder, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });

  return {
    reattached,
    remainingDetached,
    builderProject: patchedSource,
  };
}

const CONFLICT_RE = /409|conflict|changed by another|changed in another session/i;

function classify(error) {
  const msg = String(error && (error.message || error) || '');
  if (CONFLICT_RE.test(msg) || error?.status === 409 || error?.code === 409) return 'conflict';
  return 'failed';
}

export function createFoundationSaveSession() {
  let inFlight = null;

  const run = ({ sourceId, editRevision, getCurrent, saveSource, syncBuilder }) => {
    if (inFlight) return inFlight;
    const attempt = Promise.resolve().then(async () => {
      const warnings = [];
      const base = { sourceId, sourceVersion: null, savedEditRevision: editRevision, sourceSaved: false, builderSync: 'not_required', error: null, warnings };
      const isCurrent = () => {
        try {
          const c = getCurrent() || {};
          return c.sourceId === sourceId && c.editRevision === editRevision && c.loaded === true;
        } catch { return false; }
      };
      if (!isCurrent()) return { ...base, status: 'superseded' };
      let savedProject;
      try {
        savedProject = await saveSource();
      } catch (error) {
        return { ...base, status: isCurrent() ? classify(error) : 'superseded', error };
      }
      if (!savedProject || savedProject.id !== sourceId || typeof savedProject.updated_date !== 'string' || !savedProject.updated_date) {
        const error = new Error('Source save returned an unverified record.');
        return { ...base, status: isCurrent() ? classify(error) : 'superseded', error };
      }
      base.sourceSaved = true;
      base.sourceVersion = savedProject.updated_date;
      if (!isCurrent()) {
        return { ...base, status: 'superseded', builderSync: syncBuilder ? 'pending' : 'not_required' };
      }
      if (syncBuilder) {
        try {
          await syncBuilder(savedProject);
          base.builderSync = 'synced';
        } catch (error) {
          base.builderSync = 'pending';
          base.error = error;
          warnings.push('builder_sync_failed');
          return { ...base, status: isCurrent() ? 'partial' : 'superseded' };
        }
      }
      return { ...base, status: isCurrent() ? 'saved' : 'superseded' };
    });
    const shared = attempt.finally(() => { if (inFlight === shared) inFlight = null; });
    inFlight = shared;
    return shared;
  };

  return { run, isSaving: () => inFlight !== null };
}

import { isEstimateProtected } from "@/components/estimator/estimateLifecycle";
import { getOpenEstimateRevision } from "@/components/estimator/estimateRevisionService";

/**
 * Server-backed gate for Product/Part mutations that can be triggered from
 * long-lived dialogs. The UI's readOnly state is not sufficient because the
 * estimate may have changed lifecycle state in another browser session.
 *
 * draft/calculated: editable normally
 * sent/approved: editable only while an EstimateRevision is open
 * archived/cancelled: permanently locked (unarchive/restore happens through
 *   the status lifecycle, never through a Product or Part mutation)
 */
// Stale pendings must not block mutations forever — if a Builder recovery was
// abandoned mid-operation more than 24h ago, treat its pending entry as expired
// so the user isn't permanently locked out of the estimate.
const PENDING_TTL_MS = 24 * 60 * 60 * 1000;

export function getPendingEstimatePriceAcceptance(estimate) {
  const line = (estimate?.line_items || []).find((item) => {
    const pending = item?.price_acceptance_pending;
    if (!String(pending?.key || "").trim()) return false;
    const startedAt = Date.parse(pending?.started_at || "");
    if (Number.isFinite(startedAt) && Date.now() - startedAt > PENDING_TTL_MS) return false;
    return true;
  });
  return line ? { line, pending: line.price_acceptance_pending } : null;
}

export async function assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt = "", allowPriceAcceptanceKey = "" } = {}) {
  if (!estimate?.id) throw new Error("Estimate could not be verified for this change.");
  const expected = String(expectedUpdatedAt || "").trim();
  const current = String(estimate.updated_date || "").trim();
  if (expected && current !== expected) {
    throw new Error("This estimate changed in another session. Reload it before changing Products or Parts.");
  }
  const allowedKey = String(allowPriceAcceptanceKey || "").trim();
  const pendingEntry = getPendingEstimatePriceAcceptance(estimate);
  const pendingKey = String(pendingEntry?.pending?.key || "").trim();
  if (pendingKey && pendingKey !== allowedKey) {
    throw new Error("A Builder mutation is still being recovered for this Product. Resume that operation before changing Products or Parts.");
  }
  if (estimate.deleted === true) {
    throw new Error("This estimate is in Trash. Restore it before changing Products or Parts.");
  }
  const status = String(estimate.status || "draft");
  if (status === "cancelled") {
    throw new Error("This estimate is cancelled and permanently locked. Product or Part changes cannot be added.");
  }
  if (status === "archived") {
    throw new Error("This estimate is archived and locked. Restore it to an active status before changing Products or Parts.");
  }
  if (!isEstimateProtected(status)) return null;

  const revision = await getOpenEstimateRevision(estimate.id);
  if (!revision) {
    throw new Error(`This estimate is ${status} and protected. Start an Estimate Revision before adding Products or Parts.`);
  }
  return revision;
}

import { channelSellEconomics } from "./channel/channelSellPricing";

import { vinylEngineEconomics } from "./vinyl/vinylEnginePricing";

import { brickEngineEconomics } from "./brick/brickSellPricing";

import { cncEngineEconomics } from "./cnc/cncSellPricing";

import { metalEngineEconomics } from "./metal/metalSellPricing";

import { laserEngineEconomics } from "./laser/laserSellPricing";

import { paintEngineEconomics } from "./paint/paintSellPricing";

import { foundationEngineEconomics } from "./foundation/foundationSellPricing";

import { customItemsEngineEconomics } from "./customItems/customItemsSellPricing";

import { maintenanceEngineEconomics } from "./maintenance/maintenanceSellPricing";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

export function hasNumericValue(value) {
  return value !== undefined && value !== null && value !== "" && Number.isFinite(Number(value));
}

export function acceptedCustomerUnitPrice(line) {
  return hasNumericValue(line?.customer_price_snapshot)
    ? Number(line.customer_price_snapshot)
    : num(line?.total_snapshot);
}

export function liveCustomerUnitPrice(line) {
  if (hasNumericValue(line?.live_customer_price_snapshot)) return Number(line.live_customer_price_snapshot);
  if (hasNumericValue(line?.customer_price_snapshot)) return Number(line.customer_price_snapshot);
  return num(line?.live_total_snapshot, num(line?.total_snapshot));
}

export function acceptedInternalEstimateCost(lineItems = []) {
  return (lineItems || []).reduce((sum, line) => {
    const quantity = Math.max(0, num(line?.customer_quantity, 1));
    return sum + num(line?.total_snapshot) * quantity;
  }, 0);
}

export function manualCustomerPriceState({ detached = false, recalcRequired = false } = {}) {
  if (detached) return "detached_parts";
  if (recalcRequired) return "changed";
  return "manual";
}

// A Builder's source record may contain both shop/internal cost and an existing
// customer-facing sell-price calculation. Keep those concepts separate without
// changing the Builder's own established formulas.
export function sourceProjectEconomics(moduleKey, record, fallbackTotal = 0, pricingContext = null) {
  const fallback = num(fallbackTotal);
  if (!record) return { internalCost: fallback, customerPrice: fallback };

  const total = num(record.total_cost, fallback);
  const savedTierCustomerPrice = record?.customer_pricing?.applied === true && hasNumericValue(record?.customer_pricing?.total)
    ? num(record.customer_pricing.total)
    : null;
  const withSavedTier = (economics) => savedTierCustomerPrice === null
    ? economics
    : { ...economics, customerPrice: savedTierCustomerPrice };

  if (moduleKey === "foundation") {
    const cost = fallback;
    const markupPercent = num(record.customer_markup_percent);
    const override = num(record.customer_price_override);
    const baselineSell = override > 0 ? override : cost * (1 + markupPercent / 100);
    // F-23h pricing-engine wire: when the saved foundation record explicitly
    // carries engine config (engine_pricing-style context block or component-
    // scoped descriptors on the persisted split-total cost components), the
    // shared engine owns the sell side and wins over a legacy saved
    // customer_pricing snapshot. The module cost math above stays
    // authoritative; with no config the wire returns null and the record
    // keeps today's numbers byte-identically — the manual markup/override
    // and the saved Markup-Tier snapshot still apply.
    const wired = foundationEngineEconomics(record, { baselineSell, internalCost: cost, markupPercent, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: cost, customerPrice: baselineSell });
  }

  if (["vinyl", "brick_stone", "maintenance"].includes(moduleKey)) {
    const internalCost = hasNumericValue(record.subtotal)
      ? num(record.subtotal)
      : total - num(record.markup_amount);
    // F-23b/F-23c/F-23i pricing-engine wires: when the saved vinyl/brick/
    // maintenance record explicitly carries engine config (pricing_engine/
    // engine_pricing context block or per-line/component tier/template
    // descriptors), the shared engine owns the sell side and wins over a
    // legacy saved customer_pricing snapshot. The module cost math above
    // stays authoritative; with no config this returns null and the record
    // keeps today's numbers byte-identically.
    const wired = moduleKey === "vinyl"
      ? vinylEngineEconomics(record, { baselineSell: total, internalCost, pricingContext })
      : moduleKey === "brick_stone"
        ? brickEngineEconomics(record, { baselineSell: total, internalCost, pricingContext })
        : moduleKey === "maintenance"
          ? maintenanceEngineEconomics(record, { baselineSell: total, internalCost, pricingContext })
          : null;
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost, customerPrice: total });
  }

  if (moduleKey === "channel_letters") {
    const letterMarkup = num(record.total_letters_cost) - num(record.letters_subtotal);
    const projectSubtotal = hasNumericValue(record.subtotal)
      ? num(record.subtotal)
      : total - num(record.markup_amount);
    const internalCost = projectSubtotal - letterMarkup;
    // F-23a pricing-engine wire: when the saved record explicitly carries
    // engine config (pricing_engine context block or per-line tier/template
    // descriptors), the shared engine owns the sell side and wins over a
    // legacy saved customer_pricing snapshot. The module cost math above
    // stays authoritative; with no config this returns null and the record
    // keeps today's numbers byte-identically.
    const wired = channelSellEconomics(record, { internalCost, customerPrice: total });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired,
      };
    }
    return withSavedTier({ internalCost, customerPrice: total });
  }

  if (moduleKey === "cnc") {
    // F-23d pricing-engine wire: when the saved CNC record explicitly carries
    // engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot. CNC
    // total_cost is a pure cost total (no module markup), so the internal
    // cost and the sell baseline are the same number. With no config the
    // wire returns null and the record keeps today's numbers
    // byte-identically — the saved Markup-Tier snapshot still applies.
    const wired = cncEngineEconomics(record, { baselineSell: total, internalCost: total, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: total, customerPrice: total });
  }

  if (moduleKey === "laser") {
    // F-23e pricing-engine wire: when the saved laser record explicitly
    // carries engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot. Laser
    // total_cost is a pure cost total (no module markup), so the internal
    // cost and the sell baseline are the same number. With no config the
    // wire returns null and the record keeps today's numbers
    // byte-identically — the saved Markup-Tier snapshot still applies.
    const wired = laserEngineEconomics(record, { baselineSell: total, internalCost: total, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: total, customerPrice: total });
  }

  if (moduleKey === "metal") {
    const internalCost = hasNumericValue(record.subtotal)
      ? num(record.subtotal)
      : total - num(record.markup_amount);
    // F-23f pricing-engine wire: when the saved metal record explicitly
    // carries engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot. The
    // module cost math above stays authoritative; with no config the wire
    // returns null and the record keeps today's numbers byte-identically —
    // the saved Markup-Tier snapshot still applies.
    const wired = metalEngineEconomics(record, { baselineSell: total, internalCost, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost, customerPrice: total });
  }

  if (moduleKey === "painting") {
    // F-23g pricing-engine wire: when the saved paint record explicitly
    // carries engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot. Paint
    // records have no total_cost field and no module markup — the baseline
    // sell is the pure cost sum (total_paint_mask_cost +
    // total_liquid_paint_and_supplies_cost + total_labor_cost via
    // sourceProjectTotal's painting branch, which `total` resolves to since
    // record.total_cost is absent) — so the internal cost and the sell
    // baseline are the same number. With no config the wire returns null
    // and the record keeps today's numbers byte-identically — the saved
    // Markup-Tier snapshot still applies.
    const wired = paintEngineEconomics(record, { baselineSell: total, internalCost: total, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: total, customerPrice: total });
  }

  if (moduleKey === "custom_items") {
    // F-23j pricing-engine wire: when the saved custom-items record explicitly
    // carries engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot.
    // CustomItemsProject.total_cost is a pure cost total (sum of the
    // extended item_total_cost fields — no module markup), so the internal
    // cost and the sell baseline are the same number. With no config the
    // wire returns null and the record keeps today's numbers
    // byte-identically — the fallback economics and the saved Markup-Tier
    // snapshot still apply.
    const wired = customItemsEngineEconomics(record, { baselineSell: total, internalCost: total, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: fallback, customerPrice: fallback });
  }

  return withSavedTier({ internalCost: fallback, customerPrice: fallback });
}

const DEFAULT_PAGE_SIZE = 500;
const DEFAULT_MAX_ROWS = 50000;
const RATE_LIMIT_MAX_RETRIES = 3;
const RATE_LIMIT_BASE_DELAY_MS = 1200;

function rowIdentity(row, index) {
  const id = String(row?.id || "").trim();
  return id || `__row_${index}`;
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export function isRateLimitError(error) {
  const status = error?.status ?? error?.response?.status;
  if (status === 429) return true;
  const message = String(
    error?.message ||
    error?.response?.data?.error ||
    error?.data?.error ||
    ""
  ).toLowerCase();
  return message.includes("rate limit") || message.includes("too many requests");
}

/**
 * Retries a single SDK call when the platform returns a transient rate-limit
 * error. Uses exponential backoff so concurrent page-load calls (builder
 * reconciliation, part catalogs, section snapshots) don't all retry at once.
 */
export async function withRateLimitRetry(fn) {
  for (let attempt = 0; attempt <= RATE_LIMIT_MAX_RETRIES; attempt += 1) {
    try {
      return await fn();
    } catch (error) {
      // The request governor already retried this call with backoff; a second
      // retry loop here would multiply the delay without helping.
      if (typeof error?.ccsGovernorRetried === "number") throw error;
      if (attempt < RATE_LIMIT_MAX_RETRIES && isRateLimitError(error)) {
        await sleep(RATE_LIMIT_BASE_DELAY_MS * Math.pow(2, attempt));
        continue;
      }
      throw error;
    }
  }
}

/**
 * Load a complete estimator prerequisite catalog without relying on Base44's
 * list/filter default limit (50 rows).
 *
 * This helper is intentionally read-only. It pages the existing entity client
 * using the SDK's list/filter(sort, limit, skip) contract, fails closed on an
 * unreadable page, and de-duplicates by entity id so callers never silently
 * estimate from a partial catalog.
 *
 * Paging order defaults to ASCENDING "created_date" (not "-created_date").
 * That is deliberate: new rows append to the end of the set, so earlier
 * skip/limit pages stay stable while a full scan is in flight — a
 * newest-first order would shift every page on each concurrent insert.
 * Callers may pass any SDK sort string; it is forwarded to list/filter on
 * every page (an empty/falsy sort falls back to the SDK's own default).
 */
/**
 * @param {{
 *   entity?: any,
 *   query?: Record<string, any> | null,
 *   sort?: string | null,
 *   pageSize?: number,
 *   maxRows?: number,
 *   label?: string,
 *   limit?: number | null,
 * }} [options]
 */
// Short-TTL in-memory cache for slow-changing catalogs (jurisdiction/locality
// lists). Opt-in per call — repeated mounts of the same page stop re-reading
// the whole catalog and burning the shared rate-limit budget. Keyed per
// entity object (like inFlightReads): the query/sort/limits tuple alone is
// not unique — two entities with identical reads would otherwise share a
// cache slot and serve each other's rows.
const readCache = new WeakMap(); // entity -> Map<key, {at, rows}>
const CACHE_MAX_AGE_MS = 30000;
// Identical reads issued at the same instant (mount bursts, StrictMode double
// mounts, sibling components) share one network pass. Keyed per entity object
// so different gateways never share rows; every caller receives a copy so an
// in-place sort/splice by one consumer cannot corrupt another's result.
const inFlightReads = new WeakMap(); // entity -> Map<key, Promise<rows>>

const readCacheBucket = (entity) => {
  let bucket = readCache.get(entity);
  if (!bucket) {
    bucket = new Map();
    readCache.set(entity, bucket);
  }
  return bucket;
};

// Seed the short-TTL cache with rows fetched through a batch read so the
// per-entity loaders skip their own network call on the next mount.
export const primeEntityRowsCache = (entity, query, sort, rows) => {
  if (entity === null || (typeof entity !== "object" && typeof entity !== "function")) return;
  readCacheBucket(entity).set(JSON.stringify([query ?? null, sort, DEFAULT_PAGE_SIZE, DEFAULT_MAX_ROWS]), { at: Date.now(), rows });
};

export async function loadAllEntityRows({
  entity,
  query = null,
  sort = "created_date",
  pageSize = DEFAULT_PAGE_SIZE,
  maxRows = DEFAULT_MAX_ROWS,
  label = "Estimator prerequisite catalog",
  cacheTtlMs = 0,
  // (#403) `limit` bounds the total rows returned for callers that only need a
  // window (e.g. "the 50 newest"), not a verified-complete catalog. Reaching
  // the bound is a normal truncation — unlike `maxRows`, which stays a
  // runaway-scan safety net and still throws when a full scan would pass it.
  limit = null,
} = {}) {
  const parsedLimit = limit == null ? null : Math.floor(Number(limit));
  const safeLimit = Number.isFinite(parsedLimit) && parsedLimit > 0 ? parsedLimit : null;
  const canShare = entity !== null && (typeof entity === "object" || typeof entity === "function");
  const cacheKey = cacheTtlMs > 0 && canShare ? JSON.stringify([query, sort, pageSize, safeLimit ?? maxRows]) : null;
  if (cacheKey) {
    const hit = readCache.get(entity)?.get(cacheKey);
    if (hit && Date.now() - hit.at < Math.min(cacheTtlMs, CACHE_MAX_AGE_MS)) return [...hit.rows];
  }
  const hasFilter = query && typeof query === "object";
  const reader = hasFilter ? entity?.filter : entity?.list;
  if (typeof reader !== "function") {
    throw new Error(`${label} could not initialize its paged read.`);
  }

  const safePageSize = Math.max(1, Math.min(500, Number(pageSize) || DEFAULT_PAGE_SIZE));
  // A bounded read never fetches a page larger than the rows still wanted —
  // `limit: 50` costs exactly one 50-row request, not a 500-row page.
  const safeMaxRows = safeLimit ?? Math.max(safePageSize, Number(maxRows) || DEFAULT_MAX_ROWS);

  // Join an identical read already in flight instead of starting a second
  // paged scan for the same data. Non-object entities skip sharing.
  const flightKey = JSON.stringify([hasFilter ? "filter" : "list", query ?? null, sort ?? null, safePageSize, safeMaxRows]);
  if (canShare) {
    const existing = inFlightReads.get(entity)?.get(flightKey);
    if (existing) return existing.then((rows) => [...rows]);
  }

  const readPromise = (async () => {
    const collected = [];
    const seen = new Set();
    let skip = 0;

    while (skip < safeMaxRows) {
      const pageLimit = Math.min(safePageSize, safeMaxRows - skip);
      const page = await withRateLimitRetry(() =>
        hasFilter
          ? entity.filter(query, sort || undefined, pageLimit, skip)
          : entity.list(sort || undefined, pageLimit, skip)
      );

      if (!Array.isArray(page)) {
        throw new Error(`${label} could not be verified completely. Estimating was blocked rather than using a partial catalog.`);
      }

      for (let index = 0; index < page.length; index += 1) {
        const row = page[index];
        const key = rowIdentity(row, skip + index);
        if (seen.has(key)) continue;
        seen.add(key);
        collected.push(row);
      }

      if (page.length < pageLimit) {
        if (cacheKey) readCacheBucket(entity).set(cacheKey, { at: Date.now(), rows: collected });
        return collected;
      }
      skip += pageLimit;
    }

    if (safeLimit != null) {
      if (cacheKey) readCacheBucket(entity).set(cacheKey, { at: Date.now(), rows: collected });
      return collected;
    }
    throw new Error(`${label} exceeds the ${safeMaxRows.toLocaleString()}-record estimator safety limit.`);
  })();

  if (!canShare) return readPromise;
  let flightBucket = inFlightReads.get(entity);
  if (!flightBucket) {
    flightBucket = new Map();
    inFlightReads.set(entity, flightBucket);
  }
  flightBucket.set(flightKey, readPromise);
  try {
    const rows = await readPromise;
    return [...rows];
  } finally {
    if (flightBucket.get(flightKey) === readPromise) flightBucket.delete(flightKey);
  }
}
